import networkx as nx
import json
import os
import itertools
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Find an exact directed Steiner arborescence for up to ten destinations.

    The subset dynamic program stores the cheapest subtree rooted at every
    vertex, combines disjoint terminal subsets at common branch points, and
    relaxes each state over directed graph edges.  Larger instances use a
    bounded greedy shared-tree fallback.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)))
    h.remove_edges_from(list(nx.selfloop_edges(h)))
    h.remove_edges_from([
        (u, v) for u, v, data in h.edges(data=True)
        if data.get("cost") is None
    ])

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(dsts))
    if not terminals:
        return bc_topology

    def greedy():
        """Construct a valid shared tree by cheapest marginal attachment."""
        used = set()
        result = {}
        order = sorted(
            terminals,
            key=lambda d: (
                nx.shortest_path_length(h, src, d, weight="cost")
                if d in h and nx.has_path(h, src, d) else float("inf"),
                str(d),
            ),
        )
        for dst in order:
            def weight(u, v, data):
                return 0.0 if (u, v) in used else float(data["cost"])
            try:
                path = nx.dijkstra_path(h, src, dst, weight=weight)
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                return None
            result[dst] = path
            used.update(zip(path, path[1:]))
        return result

    paths = None
    if len(terminals) <= 10:
        nodes = list(h.nodes())
        index = {v: i for i, v in enumerate(nodes)}
        k = len(terminals)
        full = (1 << k) - 1
        dp = [[float("inf")] * len(nodes) for _ in range(1 << k)]
        choice = [[None] * len(nodes) for _ in range(1 << k)]

        for i, dst in enumerate(terminals):
            if dst in index:
                dp[1 << i][index[dst]] = 0.0
                choice[1 << i][index[dst]] = ("base",)

        reverse = nx.reverse_view(h)
        for mask in range(1, full + 1):
            sub = (mask - 1) & mask
            while sub:
                other = mask ^ sub
                if other and sub < other:
                    for v in nodes:
                        j = index[v]
                        value = dp[sub][j] + dp[other][j]
                        if value < dp[mask][j]:
                            dp[mask][j] = value
                            choice[mask][j] = ("merge", sub, other)
                sub = (sub - 1) & mask

            heap = [(dp[mask][i], v) for i, v in enumerate(nodes)
                    if dp[mask][i] < float("inf")]
            import heapq
            heapq.heapify(heap)
            while heap:
                value, v = heapq.heappop(heap)
                if value != dp[mask][index[v]]:
                    continue
                for u, _, data in reverse.out_edges(v, data=True):
                    candidate = value + float(data["cost"])
                    j = index[u]
                    if candidate < dp[mask][j]:
                        dp[mask][j] = candidate
                        choice[mask][j] = ("edge", v)
                        heapq.heappush(heap, (candidate, u))

        root = index.get(src)
        edges = set()
        seen = set()

        def recover(mask, vertex):
            state = (mask, vertex)
            if state in seen:
                return
            seen.add(state)
            item = choice[mask][index[vertex]]
            if item is None:
                return
            if item[0] == "merge":
                recover(item[1], vertex)
                recover(item[2], vertex)
            elif item[0] == "edge":
                nxt = item[1]
                edges.add((vertex, nxt))
                recover(mask, nxt)

        if root is not None and dp[full][root] < float("inf"):
            recover(full, src)
            tree = nx.DiGraph()
            tree.add_edges_from(edges)
            if all(dst in tree and nx.has_path(tree, src, dst)
                   for dst in terminals):
                paths = {
                    dst: nx.shortest_path(tree, src, dst)
                    for dst in terminals
                }

    if paths is None:
        paths = greedy()

    if paths is None:
        paths = {
            dst: nx.dijkstra_path(h, src, dst, weight="cost")
            for dst in terminals
        }

    for dst in terminals:
        records = [[u, v, G[u][v]] for u, v in zip(paths[dst], paths[dst][1:])]
        for partition in range(bc_topology.num_partitions):
            for record in records:
                bc_topology.append_dst_partition_path(dst, partition, record)
    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]


class BroadCastTopology:
    def __init__(
        self,
        src: str,
        dsts: List[str],
        num_partitions: int = 4,
        paths: Dict[str, SingleDstPath] = None,
    ):
        self.src = src
        self.dsts = dsts
        self.num_partitions = num_partitions

        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {
                dst: {str(i): None for i in range(num_partitions)}
                for dst in dsts
            }

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)


